using System.Numerics;
using System.Text.Json;
using DCWallet.Core;
using Decimal.Web3;
using Decimal.Web3.Staking;
using Decimal.Web3.Tokens;
using Decimal.Web3.TokenEconomy;
using Decimal.Web3.Transactions;
namespace DCWallet.Tests;
/// <summary>Root-only submission: new reserved-token purchase delta, never preexisting assets.</summary>
public static class Erc20StakingNetworkScenario
{
 public const string Token="0x37748f3e857a71e4334125a935052ce1e603b7b5",Validator="0x05BaBC196B96C22f763f7e30a84E74665A920f98";
 public sealed record Baseline(BigInteger Balance,BigInteger Allowance,BigInteger Stake,BigInteger NewAmountRaw=default);
 public sealed record Pending(string BalanceRaw,string AllowanceRaw,string StakeRaw,string RequestIndex,string UnfreezeTimestamp,string WithdrawalHash,string AmountRaw="1") {[System.Text.Json.Serialization.JsonIgnore]public Baseline Baseline=>new(BigInteger.Parse(BalanceRaw),BigInteger.Parse(AllowanceRaw),BigInteger.Parse(StakeRaw),BigInteger.Parse(AmountRaw));}
 static Erc20Service TokenService(AdvancedTestContext c)=>new(c.Client,Token);
 static StakeReader Stakes(AdvancedTestContext c)=>new(c.Client.Web3,CombinedNftDelegation.Proxy);
 static DelegationDrafts Drafts(AdvancedTestContext c)=>new(c.Network,CombinedNftDelegation.Proxy);
 public static async Task<Baseline> ReadBaselineAsync(AdvancedTestContext ctx){await CombinedNftDelegation.VerifyAsync(ctx.Client);return new(await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetBalanceRawAsync(ctx.Owner)),await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetAllowanceRawAsync(ctx.Owner,CombinedNftDelegation.Proxy)),(await AdvancedTestContext.ReadOnlyRetryAsync(()=>Stakes(ctx).GetStakeAsync(Validator,ctx.Owner,Token))).AmountRaw);}
 public static async Task<Pending> BeginAsync(AdvancedTestContext ctx,bool permit=true){
  var baseline=await ReadBaselineAsync(ctx);ctx.Note("ERC20 reserve staking original baseline",new{token=Token,balanceRaw=baseline.Balance.ToString(),allowanceRaw=baseline.Allowance.ToString(),stakeRaw=baseline.Stake.ToString()});
  var economy=new ReservableTokenService(ctx.Client,Token);var quote=await economy.CalculateBuyOutputRawAsync(Units.Parse("0.001"));if(quote<=0)throw new InvalidOperationException("No positive purchase quote.");
  var center=await AdvancedTestContext.ReadOnlyRetryAsync(()=>ctx.Client.ResolveSystemContractAsync("token-center"));var buy=new TokenEconomyDrafts(center).BuildBuyTokenForExactDelDraft(ctx.Owner,Token,Units.Parse("0.001"),BigInteger.Max(1,quote*99/100),ctx.Owner);await ctx.Client.EstimateFeeAsync(buy);
  await ctx.SendAsync("ERC20 staking buy only new reserve-token delta .001 tDEL",buy);var amount=await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetBalanceRawAsync(ctx.Owner))-baseline.Balance;if(amount<=0)throw new InvalidOperationException("Purchase delta not positive.");baseline=baseline with{NewAmountRaw=amount};ctx.Note("ERC20 purchase delta recovery before delegation",new{balanceRaw=baseline.Balance.ToString(),allowanceRaw=baseline.Allowance.ToString(),stakeRaw=baseline.Stake.ToString(),amountRaw=amount.ToString()});
  return await DelegateAndWithdrawAsync(ctx,baseline,permit);
 }
 public static async Task<Pending> DelegateAndWithdrawAsync(AdvancedTestContext ctx,Baseline baseline,bool permit=true){RequireAmount(baseline);await RequireBalanceAsync(ctx,baseline.Balance+baseline.NewAmountRaw);if(!permit){var approval=await StageExactApprovalAsync(ctx,baseline);if(approval is not null)await ctx.SendAsync("ERC20 staking exact purchase-delta approval",approval);}var draft=await StageDelegateAsync(ctx,baseline,permit);await ctx.SendAsync(permit?"ERC20 staking delegate purchase delta by permit":"ERC20 staking delegate purchase delta allowance",draft);ctx.Note("ERC20 newly delegated before withdraw",new{balanceRaw=baseline.Balance.ToString(),allowanceRaw=baseline.Allowance.ToString(),stakeRaw=baseline.Stake.ToString(),amountRaw=baseline.NewAmountRaw.ToString()});return await WithdrawAsync(ctx,baseline);}
 static void RequireAmount(Baseline b){if(b.NewAmountRaw<=0)throw new InvalidOperationException("Only a measured new purchase delta may be staked.");}
 public static async Task<TransactionDraft?> StageExactApprovalAsync(AdvancedTestContext ctx,Baseline b){RequireAmount(b);await RequireBalanceAsync(ctx,b.Balance+b.NewAmountRaw);if(await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetAllowanceRawAsync(ctx.Owner,CombinedNftDelegation.Proxy))>=b.NewAmountRaw)return null;var draft=TokenService(ctx).BuildApproveDraft(ctx.Owner,CombinedNftDelegation.Proxy,b.NewAmountRaw);await ctx.Client.EstimateFeeAsync(draft);return draft;}
 public static async Task<TransactionDraft> StageDelegateAsync(AdvancedTestContext ctx,Baseline b,bool permit=false){RequireAmount(b);await CombinedNftDelegation.VerifyAsync(ctx.Client);await RequireBalanceAsync(ctx,b.Balance+b.NewAmountRaw);if((await AdvancedTestContext.ReadOnlyRetryAsync(()=>Stakes(ctx).GetStakeAsync(Validator,ctx.Owner,Token))).AmountRaw!=b.Stake)throw new InvalidOperationException("Stake baseline changed.");TransactionDraft draft;if(permit){var expiry=DateTimeOffset.UtcNow.AddMinutes(10).ToUnixTimeSeconds();var sig=await new Erc20PermitService(ctx.Client,Token).SignAsync(CombinedNftDelegation.Proxy,b.NewAmountRaw,expiry,ctx.Signer);draft=Drafts(ctx).BuildDelegateByPermitDraft(ctx.Owner,Validator,Token,b.NewAmountRaw,sig.Deadline,sig.V,sig.R,sig.S);}else{if(await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetAllowanceRawAsync(ctx.Owner,CombinedNftDelegation.Proxy))<b.NewAmountRaw)throw new InvalidOperationException("Exact approval required.");draft=Drafts(ctx).BuildDelegateErc20Draft(ctx.Owner,Validator,Token,b.NewAmountRaw);}await ctx.Client.EstimateFeeAsync(draft);return draft;}
 public static async Task<TransactionDraft> StageWithdrawNewUnitAsync(AdvancedTestContext ctx,Baseline b){RequireAmount(b);await CombinedNftDelegation.VerifyAsync(ctx.Client);if((await AdvancedTestContext.ReadOnlyRetryAsync(()=>Stakes(ctx).GetStakeAsync(Validator,ctx.Owner,Token))).AmountRaw!=b.Stake+b.NewAmountRaw)throw new InvalidOperationException("Stake differs from exact new purchase delta.");await RequireBalanceAsync(ctx,b.Balance);var draft=Drafts(ctx).BuildWithdrawDraft(ctx.Owner,Validator,Token,b.NewAmountRaw);await ctx.Client.EstimateFeeAsync(draft);return draft;}
 public static async Task<Pending> WithdrawAsync(AdvancedTestContext ctx,Baseline baseline){var withdrawal=await StageWithdrawNewUnitAsync(ctx,baseline);var receipt=await ctx.SendAsync("ERC20 staking withdraw only new purchase delta",withdrawal);var events=WithdrawalReceiptReader.DecodeReceipt(receipt,CombinedNftDelegation.Proxy);if(events.Count!=1)throw new InvalidOperationException("Expected one withdrawal event.");var e=events[0];if(!e.Stake.Delegator.Equals(ctx.Owner,StringComparison.OrdinalIgnoreCase)||!e.Stake.Token.Equals(Token,StringComparison.OrdinalIgnoreCase)||e.Stake.AmountRaw!=baseline.NewAmountRaw||!e.Stake.Validator.Equals(Validator,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Withdrawal coordinates mismatch.");var pending=new Pending(baseline.Balance.ToString(),baseline.Allowance.ToString(),baseline.Stake.ToString(),e.StakeIndex.ToString(),e.UnfreezeTimestamp.ToString(),receipt.TransactionHash,baseline.NewAmountRaw.ToString());ctx.Note("ERC20 staking pending recovery",pending);await File.WriteAllTextAsync(Path.Combine(ctx.DirectoryPath,"erc20-staking-pending.json"),JsonSerializer.Serialize(pending));var restore=await StageRestoreAllowanceAsync(ctx,baseline);if(restore is not null)await ctx.SendAsync("ERC20 staking restore original allowance",restore);return pending;}
 public static async Task<TransactionDraft> StageCompleteAsync(AdvancedTestContext ctx,BigInteger index,BigInteger amount){await CombinedNftDelegation.VerifyAsync(ctx.Client);var f=await new FrozenStakeReader(ctx.Client.Web3,CombinedNftDelegation.Proxy).GetFrozenStakeAsync(index);if(!f.IsMatured(DateTimeOffset.UtcNow.ToUnixTimeSeconds())||!f.Stake.Delegator.Equals(ctx.Owner,StringComparison.OrdinalIgnoreCase)||!f.Stake.Token.Equals(Token,StringComparison.OrdinalIgnoreCase)||!f.Stake.Validator.Equals(Validator,StringComparison.OrdinalIgnoreCase)||f.Stake.AmountRaw!=amount)throw new InvalidOperationException("Exact owned matured withdrawal required.");var draft=Drafts(ctx).BuildCompleteDraft(ctx.Owner,new[]{index});await ctx.Client.EstimateFeeAsync(draft);return draft;}
 public static async Task CompleteAsync(AdvancedTestContext ctx,Pending p){var receipt=await ctx.Client.Web3.Eth.Transactions.GetTransactionReceipt.SendRequestAsync(p.WithdrawalHash)??throw new InvalidOperationException("Withdrawal receipt unavailable.");var events=WithdrawalReceiptReader.DecodeReceipt(receipt,CombinedNftDelegation.Proxy);if(events.Count!=1||events[0].StakeIndex.ToString()!=p.RequestIndex||events[0].UnfreezeTimestamp.ToString()!=p.UnfreezeTimestamp)throw new InvalidOperationException("Pending receipt proof differs.");await ctx.SendAsync("ERC20 staking complete only new purchase delta",await StageCompleteAsync(ctx,BigInteger.Parse(p.RequestIndex),p.Baseline.NewAmountRaw));await SellRestoredDeltaAsync(ctx,p);}
 public static async Task SellRestoredDeltaAsync(AdvancedTestContext ctx,Pending p){var b=p.Baseline;RequireAmount(b);var frozen=await AdvancedTestContext.ReadOnlyRetryAsync(()=>new FrozenStakeReader(ctx.Client.Web3,CombinedNftDelegation.Proxy).GetFrozenStakeAsync(BigInteger.Parse(p.RequestIndex)));if(frozen.FreezeStatus!=0)throw new InvalidOperationException("Withdrawal not completed.");if((await AdvancedTestContext.ReadOnlyRetryAsync(()=>Stakes(ctx).GetStakeAsync(Validator,ctx.Owner,Token))).AmountRaw!=b.Stake)throw new InvalidOperationException("Original stake differs.");await RequireBalanceAsync(ctx,b.Balance+b.NewAmountRaw);var quote=await AdvancedTestContext.ReadOnlyRetryAsync(()=>new ReservableTokenService(ctx.Client,Token).CalculateSellOutputWeiAsync(b.NewAmountRaw));if(quote<=0)throw new InvalidOperationException("Positive sale quote required.");var center=await AdvancedTestContext.ReadOnlyRetryAsync(()=>ctx.Client.ResolveSystemContractAsync("token-center"));var sale=new TokenEconomyDrafts(center).BuildSellExactTokensForDelDraft(ctx.Owner,Token,b.NewAmountRaw,BigInteger.Max(1,quote*99/100),ctx.Owner);await AdvancedTestContext.ReadOnlyRetryAsync(()=>ctx.Client.EstimateFeeAsync(sale));await ctx.SendAsync("ERC20 staking sell only restored purchase delta",sale);await VerifyRestoredAsync(ctx,b);ctx.Note("ERC20 stake original baseline restored",new{balanceRaw=b.Balance.ToString(),amountSoldRaw=b.NewAmountRaw.ToString()});}
 public static async Task<TransactionDraft?> StageRestoreAllowanceAsync(AdvancedTestContext ctx,Baseline b){if(await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetAllowanceRawAsync(ctx.Owner,CombinedNftDelegation.Proxy))==b.Allowance)return null;var draft=TokenService(ctx).BuildApproveDraft(ctx.Owner,CombinedNftDelegation.Proxy,b.Allowance);await ctx.Client.EstimateFeeAsync(draft);return draft;}
 public static async Task VerifyRestoredAsync(AdvancedTestContext ctx,Baseline b){await RequireBalanceAsync(ctx,b.Balance);if((await AdvancedTestContext.ReadOnlyRetryAsync(()=>Stakes(ctx).GetStakeAsync(Validator,ctx.Owner,Token))).AmountRaw!=b.Stake||await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetAllowanceRawAsync(ctx.Owner,CombinedNftDelegation.Proxy))!=b.Allowance)throw new InvalidOperationException("Original stake/allowance differs.");}
 static async Task RequireBalanceAsync(AdvancedTestContext ctx,BigInteger expected){if(await AdvancedTestContext.ReadOnlyRetryAsync(()=>TokenService(ctx).GetBalanceRawAsync(ctx.Owner))!=expected)throw new InvalidOperationException("QA token balance changed.");}
}
